   122	Encoder::Encoder(FrameWritePointer &aWritePointer)
   123	    : mWritePointer(aWritePointer)
   124	    , mFcs(0)
   125	{
   126	}
   127	
   128	otError Encoder::BeginFrame(void)
   129	{
   130	    mFcs = kInitFcs;
   131	
   132	    return mWritePointer.WriteByte(kFlagSequence);
   133	}
   134	
   135	otError Encoder::Encode(uint8_t aByte)
   136	{
   137	    otError error = OT_ERROR_NONE;
   138	
   139	    if (HdlcByteNeedsEscape(aByte))
   140	    {
   141	        VerifyOrExit(mWritePointer.CanWrite(2), error = OT_ERROR_NO_BUFS);
   142	
   143	        mWritePointer.WriteByte(kEscapeSequence);
   144	        mWritePointer.WriteByte(aByte ^ 0x20);
   145	    }
   146	    else
   147	    {
   148	        SuccessOrExit(error = mWritePointer.WriteByte(aByte));
   149	    }
   150	
   151	    mFcs = UpdateFcs(mFcs, aByte);
   152	
   153	exit:
   154	    return error;
   155	}
   156	
   157	otError Encoder::Encode(const uint8_t *aData, uint16_t aLength)
   158	{
   159	    otError           error      = OT_ERROR_NONE;
   160	    uint16_t          oldFcs     = mFcs;
   161	    FrameWritePointer oldPointer = mWritePointer;
   162	
   163	    while (aLength--)
   164	    {
   165	        SuccessOrExit(error = Encode(*aData++));
   166	    }
   167	
   168	exit:
   169	
   170	    if (error != OT_ERROR_NONE)
   171	    {
   172	        mWritePointer = oldPointer;
   173	        mFcs          = oldFcs;
   174	    }
   175	
   176	    return error;
   177	}
   178	
   179	otError Encoder::EndFrame(void)
   180	{
   181	    otError           error      = OT_ERROR_NONE;
   182	    FrameWritePointer oldPointer = mWritePointer;
   183	    uint16_t          oldFcs     = mFcs;
   184	    uint16_t          fcs        = mFcs;
   185	
   186	    fcs ^= 0xffff;
   187	
   188	    SuccessOrExit(error = Encode(fcs & 0xff));
   189	    SuccessOrExit(error = Encode(fcs >> 8));
   190	
   191	    SuccessOrExit(error = mWritePointer.WriteByte(kFlagSequence));
   192	
   193	exit:
   194	
   195	    if (error != OT_ERROR_NONE)
   196	    {
   197	        mWritePointer = oldPointer;
   198	        mFcs          = oldFcs;
   199	    }
   200	
   201	    return error;
   202	}
