   202	    aMessage.Read(offset, length, tlvs);
   203	
   204	    // Session Id and Border Router Locator MUST NOT be set, but accept including unexpected or
   205	    // unknown TLV as long as there is at least one valid TLV.
   206	    cur = reinterpret_cast<MeshCoP::Tlv *>(tlvs);
   207	    end = reinterpret_cast<MeshCoP::Tlv *>(tlvs + length);
   208	
   209	    while (cur < end)
   210	    {
   211	        MeshCoP::Tlv::Type type;
   212	
   213	        VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end);
   214	
   215	        type = cur->GetType();
   216	
   217	        if (type == MeshCoP::Tlv::kJoinerUdpPort || type == MeshCoP::Tlv::kSteeringData)
   218	        {
   219	            hasValidTlv = true;
   220	        }
   221	        else if (type == MeshCoP::Tlv::kBorderAgentLocator)
   222	        {
   223	            ExitNow();
   224	        }
   225	        else if (type == MeshCoP::Tlv::kCommissionerSessionId)
   226	        {
   227	            MeshCoP::CommissionerSessionIdTlv *tlv = static_cast<MeshCoP::CommissionerSessionIdTlv *>(cur);
   228	
   229	            VerifyOrExit(tlv->IsValid());
   230	            sessionId    = tlv->GetCommissionerSessionId();
   231	            hasSessionId = true;
   232	        }
   233	        else
   234	        {
   235	            // do nothing for unexpected or unknown TLV
   236	        }
   237	
   238	        cur = cur->GetNext();
   239	    }
   240	
   241	    // verify whether or not commissioner session id TLV is included
   242	    VerifyOrExit(hasSessionId);
   243	
   244	    // verify whether or not MGMT_COMM_SET.req includes at least one valid TLV
   245	    VerifyOrExit(hasValidTlv);
   246	
   247	    // Find Commissioning Data TLV
   248	    for (NetworkDataTlv *netDataTlv = reinterpret_cast<NetworkDataTlv *>(mTlvs);
   249	         netDataTlv < reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength); netDataTlv = netDataTlv->GetNext())
   250	    {
   251	        if (netDataTlv->GetType() == NetworkDataTlv::kTypeCommissioningData)
   252	        {
   253	            // Iterate over MeshCoP TLVs and extract desired data
   254	            for (cur = reinterpret_cast<MeshCoP::Tlv *>(netDataTlv->GetValue());
   255	                 cur < reinterpret_cast<MeshCoP::Tlv *>(netDataTlv->GetValue() + netDataTlv->GetLength());
   256	                 cur = cur->GetNext())
   257	            {
   258	                if (cur->GetType() == MeshCoP::Tlv::kCommissionerSessionId)
   259	                {
   260	                    VerifyOrExit(sessionId ==
   261	                                 static_cast<MeshCoP::CommissionerSessionIdTlv *>(cur)->GetCommissionerSessionId());
   262	                }
   263	                else if (cur->GetType() == MeshCoP::Tlv::kBorderAgentLocator)
   264	                {
   265	                    VerifyOrExit(length + cur->GetSize() <= sizeof(tlvs));
   266	                    memcpy(tlvs + length, reinterpret_cast<uint8_t *>(cur), cur->GetSize());
   267	                    length += cur->GetSize();
   268	                }
   269	            }
   270	        }
   271	    }
   272	
   273	    SetCommissioningData(tlvs, static_cast<uint8_t>(length));
   274	
   275	    state = MeshCoP::StateTlv::kAccept;
   276	
   277	exit:
   278	
   279	    if (Get<Mle::MleRouter>().GetRole() == OT_DEVICE_ROLE_LEADER)
   280	    {
   281	        SendCommissioningSetResponse(aMessage, aMessageInfo, state);
   282	    }
   283	}
